# (...) argument forwarding as generated by ActiveSupport 8.1 `delegate` (querying.rb delegates
# `where`, `find`, `pluck`, ... to `all`)
require_relative 'harness'

class Relation
  def where(*args) = self
  def find(*args) = self
  def where_kw(opts = :chain, *rest) = self
end

class Model
  RELATION = Relation.new
  def self.all = RELATION

  # what `delegate :where, :find, to: :all` (active_support/delegation.rb) generates
  def self.where(...)
    _ = all
    _.where(...)
  end

  def self.find(...)
    _ = all
    _.find(...)
  end

  # the same delegation spelled out
  def self.where_explicit(*args)
    all.where(*args)
  end
end

RailsBench.run(
  'baseline: Model.all.where(hash)'                            => 'Model.all.where(char_test: 1)',
  'Model.where(char_test: v) (delegated via ...)'              => 'Model.where(char_test: 1)',
  'Model.find(id) (delegated via ...)'                         => 'Model.find(501)',
  'Model.where_explicit(hash) (*args)'                         => 'Model.where_explicit(char_test: 1)'
)
